"""Snippets run on both real PySpark and the trainer's PySpark-compatible layer (see test_matches_real_pyspark.py).

Each case is (name, code, ordered, compare_show). The code assigns a DataFrame to `result`.
"""

P = "from pyspark.sql import functions as F, Row\nfrom pyspark.sql.window import Window\nfrom pyspark.sql.types import *\no=spark.table('orders'); c=spark.table('customers'); p=spark.table('products'); oi=spark.table('order_items'); ev=spark.table('bronze_events'); ca=spark.table('carts')\n"
C = []  # (name, code, ordered, show)
def add(name, body, ordered=False, show=False): C.append((name, P + body, ordered, show))

# ---- selection / columns
add("select-strings", "result = c.select('customer_id','name')", True, True)
add("select-star-plus", "result = c.select('*', F.lit(1).alias('one'))")
add("withColumn-replace", "result = p.withColumn('price', F.col('price')*2)", True, True)
add("withColumn-expr-name", "result = p.select(F.col('price')*2, F.col('price')+1, F.col('price')/3, -F.col('price'))", True, True)
add("rename+drop", "result = p.withColumnRenamed('price','p').drop('category')", True)
add("selectExpr", "result = p.selectExpr('product_id*2 as dbl','upper(product_name) as n')", True)
add("alias-select", "result = p.select(F.col('price').alias('p'), p.product_name.alias('n'))", True)
add("toDF", "result = p.toDF('a','b','c','d')", True)
add("drop-missing-col", "result = p.drop('nope')", True)
add("column-attr-access", "result = p.filter(p.price > 40).select(p.product_name)", True)
add("getitem-access", "result = p.filter(p['price'] > 40).select(p['product_name'])", True)
# ---- filtering
add("filter-and-or", "result = o.filter((F.col('status')=='COMPLETED') & ((F.col('customer_id')==1) | (F.col('customer_id')==2)))")
