add("isin", "result = o.filter(F.col('status').isin('PENDING','CANCELLED'))")
add("isin-list-not", "result = o.filter(~F.col('status').isin(['PENDING','CANCELLED']))")
add("between", "result = p.filter(F.col('price').between(12.5, 55))")
add("like", "result = c.filter(F.col('name').like('%a%'))")
add("rlike", "result = c.filter(F.col('email').rlike('^[a-d]'))")
add("startswith-contains", "result = c.filter(F.col('name').startswith('A') | F.col('name').contains('Li'))")
add("null-filters", "result = c.filter(F.col('email').isNull() | F.col('country').isNull())")
add("eq-null-is-empty", "result = c.filter(F.col('email') == None)")
add("eqNullSafe", "result = c.filter(F.col('country').eqNullSafe(None))")
add("date-string-compare", "result = o.filter(F.col('order_date') >= '2024-03-01')")
add("date-lit-compare", "result = o.filter(F.col('order_date') > F.lit('2024-03-01').cast('date'))")
add("filter-in-where", "result = o.where(F.col('order_id') > 1005)")
# ---- when/otherwise
add("when-otherwise", "result = p.withColumn('b', F.when(F.col('price')>=100,'premium').when(F.col('price')>=40,'standard').otherwise('budget'))", True)
add("when-no-otherwise", "result = p.withColumn('b', F.when(F.col('price')>=100,'premium'))", True)
add("when-numeric-mix", "result = p.withColumn('b', F.when(F.col('price')>=100, 1).otherwise(0.5))", True)
add("when-null-cond", "result = c.withColumn('b', F.when(F.col('country')=='US','us').otherwise('other'))", True)
# ---- nulls
add("fillna-str", "result = c.fillna('UNKNOWN')", True)
add("fillna-dict", "result = c.fillna({'country':'?','email':'none'})", True)
add("fillna-num-leaves-str", "result = c.fillna(0)", True)
add("fillna-subset", "result = c.fillna('X', subset=['country'])", True)
add("dropna-any", "result = c.dropna()", True)
add("dropna-all", "result = c.dropna(how='all', subset=['email','country'])", True)
add("dropna-thresh", "result = c.dropna(thresh=5)", True)
add("dropna-subset", "result = c.dropna(subset=['email'])", True)
add("na-fill", "result = c.na.fill('Z')", True)
